public static int steps(int n) {
    int count = 0;
    while (n != 1) {
        if (n % 2 == 0) {
            n = n / 2;
        } else {
            n = 3 * n + 1;
        }
        count++;
    }
    return count;
}

public static int longest(int a, int b) {
    int best = a;
    for (int n = a + 1; n <= b; n++) {
        if (steps(n) > steps(best)) {
            best = n;
        }
    }
    return best;
}

